#!/usr/bin/env bash
set -euo pipefail
umask 077
: "${JOB_UID:?}" "${POD_UID:?}" "${FLEET_API_KEY:?}" "${DEDICATED_SERVICE_ORIGIN:?}"
ROOT=/workspace/cyber-post-train
mkdir -p "$ROOT/evals/fleet/configs"; touch "$ROOT/evals/__init__.py" "$ROOT/evals/fleet/__init__.py"
for binding in self_hosted.py:self_hosted.py runner.py:opencode_train_sweep_runner.py endpoint_lease.py:endpoint_lease.py predecessor.py:exact_pass4_bulk_v3.py engine.py:exact_pass4_bulk_runtime_v3.py universe.py:exact_pass4_universe.py crypto.py:exact_pass4_crypto.py inventory.py:exact_pass4_task_inventory.py hosted_bulk.py:hosted_glm_exact_bulk_v1.py hosted_bulk_runtime.py:hosted_glm_exact_bulk_runtime_v1.py hosted_release.py:hosted_glm_exact_bulk_release_v1.py base_canary.py:glm53_dedicated_v14_scored_canary_v1.py base_runtime.py:glm53_dedicated_v14_scored_canary_runtime_v1.py dedicated_canary.py:glm53_dedicated_v19_a2_v1.py dedicated_runtime.py:glm53_dedicated_v19_a2_runtime_v1.py old_release.py:glm53_dedicated_v15_canary_release_v1.py release.py:glm53_dedicated_v19_a2_release_v1.py; do install -m 0644 "/bootstrap/${binding%%:*}" "$ROOT/evals/fleet/${binding#*:}"; done
for binding in campaign.json:q38-glm53-exact-easiest100-pass4-campaign-v1.json selection.json:opencode-easiest-train100-selection-v2.json glm-template.json:glm53-opencode-autocontinue-canary1-v1.json qwen-template.json:qwen38-opencode-autocontinue-canary1-v1.json bulk-qwen-a.json:exact-pass4-bulk-qwen-a-v3.json bulk-qwen-b.json:exact-pass4-bulk-qwen-b-v3.json bulk-glm-a.json:exact-pass4-bulk-glm-a-v3.json bulk-glm-b.json:exact-pass4-bulk-glm-b-v3.json; do install -m 0644 "/bootstrap/${binding%%:*}" "$ROOT/evals/fleet/configs/${binding#*:}"; done
cd "$ROOT"; E=$ROOT/.dedicated-evidence; install -d -m 0700 "$E"; install -m 0600 /bootstrap/parity.json "$E/parity.json"; install -m 0600 /bootstrap/binding.json "$E/binding.json"; install -m 0600 /bootstrap/controller-package.json "$E/controller-package.json"
export DEDICATED_PARITY_PATH=$E/parity.json DEDICATED_BINDING_PATH=$E/binding.json
uv run --no-project --with httpx==0.28.1 python -c 'from pathlib import Path; from evals.fleet.glm53_dedicated_v19_a2_release_v1 import build,OUTPUT; from evals.fleet import exact_pass4_bulk_runtime_v3 as e; r=build(Path.cwd(),Path(".dedicated-evidence/controller-package.json")); OUTPUT.parent.mkdir(mode=0o700,parents=True,exist_ok=False); e._write_once(OUTPUT,r)'
